 public static string DesktopFolder {get{return Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);}}
 void PreferenceChanged(object sender,Microsoft.Win32.UserPreferenceChangedEventArgs e){UI(()=>{ApplyPalette(Palette.SystemPalette());Preview();});}
 protected override void OnHandleCreated(EventArgs e){base.OnHandleCreated(e);ApplyPalette(Palette.SystemPalette());}
 protected override void WndProc(ref Message m){base.WndProc(ref m);if(m.Msg==0x001A||m.Msg==0x031A)UI(()=>{ApplyPalette(Palette.SystemPalette());Preview();});}
 internal void ApplyPalette(Palette value){palette=value;SuspendLayout();PaintControls(this,value);WindowTheme.Caption(this,value);tips.BackColor=value.Card;tips.ForeColor=value.Text;if(logWindow!=null&&!logWindow.IsDisposed){PaintControls(logWindow,value);WindowTheme.Caption(logWindow,value);}ResumeLayout(false);Invalidate(true);}
 static void PaintControls(Control c,Palette t){
  var surface=c as Surface;var button=c as Button;var label=c as Label;var combo=c as ComboBox;
  if(c is Form){c.BackColor=t.Window;c.ForeColor=t.Text;}
  else if(surface!=null){surface.BackColor=t.Card;surface.BorderColor=t.Border;}
  else if(button!=null){bool primary=Equals(button.Tag,"primary");button.BackColor=primary?Color.FromArgb(18,113,103):t.Button;button.ForeColor=primary?Color.White:t.Text;button.FlatAppearance.BorderColor=t.Border;button.FlatAppearance.MouseOverBackColor=primary?Color.FromArgb(24,134,121):t.Hover;button.FlatAppearance.MouseDownBackColor=t.Hover;}
  else if(c is TextBoxBase||c is NumericUpDown||combo!=null){c.BackColor=c.Enabled?t.Input:t.Card;c.ForeColor=c.Enabled?t.Text:t.Disabled;if(combo!=null)combo.FlatStyle=FlatStyle.Flat;WindowTheme.Input(c,t);}
  else {c.BackColor=c.Parent==null?t.Window:c.Parent.BackColor;c.ForeColor=t.TextColor(c.Tag);}
  if(label!=null)label.ForeColor=t.TextColor(label.Tag);
  var themedButton=c as ThemeButton;if(themedButton!=null)themedButton.Colors=t;
  var themedCheck=c as ThemeCheckBox;if(themedCheck!=null)themedCheck.Colors=t;
  var themedCombo=c as ThemeComboBox;if(themedCombo!=null)themedCombo.Colors=t;
  foreach(Control child in c.Controls)PaintControls(child,t);c.Invalidate();
 }
 static TableLayoutPanel Grid(int columns,int rows){var grid=new TableLayoutPanel{ColumnCount=columns,RowCount=rows,Margin=Padding.Empty,Padding=Padding.Empty};if(rows==1)grid.RowStyles.Add(new RowStyle(SizeType.Percent,100));if(columns==1)grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));return grid;}
