 static void Style(Label l,float size,Color color,bool bold){l.Font=new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular);l.Tag=color==Muted?TextTone.Muted:color==Accent?TextTone.Accent:color==Color.FromArgb(142,93,30)?TextTone.Warning:TextTone.Main;l.ForeColor=color;l.Dock=DockStyle.Fill;l.TextAlign=ContentAlignment.MiddleLeft;l.AutoEllipsis=true;l.Margin=Padding.Empty;}
