  format.Items.AddRange(new object[]{"TXT text","Excel workbook (.xlsx)","TXT + Excel"});format.SelectedIndex=2;
  repeat.Minimum=1;repeat.Maximum=40;repeat.Value=6;count.Maximum=1000000000;count.Value=1;seconds.Maximum=315360000;
  sensitive.Text="Match case";sensitive.AutoSize=true;sensitive.Dock=DockStyle.Right;sensitive.Margin=Padding.Empty;append.Text="Append to this network's TXT file";append.AutoSize=true;append.Margin=Padding.Empty;append.Tag=TextTone.Muted;append.ForeColor=Muted;
  folder.Text=DesktopFolder;folder.AccessibleName="Output folder";
