 void BuildRules(){var g=Grid(1,6);g.Dock=DockStyle.Fill;int[] h={24,46,46,46,46,1};for(int i=0;i<6;i++)g.RowStyles.Add(new RowStyle(i==5?SizeType.Percent:SizeType.Absolute,i==5?100:h[i]));var head=Grid(2,1);head.Dock=DockStyle.Fill;head.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,60));head.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,40));head.Controls.Add(Label("01  Match rules",11,Ink,true),0,0);head.Controls.Add(sensitive,1,0);g.Controls.Add(head,0,0);g.Controls.Add(Input("Network",chain),0,1);g.Controls.Add(Input("Suffix mode",mode),0,2);g.Controls.Add(Pair(Input("Prefix · optional",prefix),Input("Suffix · optional",suffix)),0,3);g.Controls.Add(Pair(Input("Repeat length",repeat),Input("Characters · editable",chars)),0,4);Style(ruleHelp,8.5F,Muted,false);ruleHelp.Padding=new Padding(0,2,0,0);g.Controls.Add(ruleHelp,0,5);rulesCard.Controls.Add(g);}
