 Control Metric(string caption,Label value,string initial){var card=new Surface{Dock=DockStyle.Fill,Margin=new Padding(0,0,value==elapsedValue?0:8,0),Padding=new Padding(12,8,12,8)};var g=Grid(1,2);g.Dock=DockStyle.Fill;g.RowStyles.Add(new RowStyle(SizeType.Absolute,20));g.RowStyles.Add(new RowStyle(SizeType.Percent,100));g.Controls.Add(Label(caption,8,Muted,false),0,0);Style(value,18,Ink,true);value.Text=initial;g.Controls.Add(value,0,1);card.Controls.Add(g);return card;}
 Options Read(){string[] c={"all","digits","letters","lower","upper"};return new Options{Rule=new Rules{Chain=chain.SelectedIndex==0?"eth":chain.SelectedIndex==1?"tron":"polygon",Prefix=prefix.Text.Trim(),Suffix=mode.SelectedIndex==0?suffix.Text.Trim():"",Repeat=mode.SelectedIndex==1?(int)repeat.Value:0,CharChoice=chars.SelectedIndex>=0?c[chars.SelectedIndex]:chars.Text.Trim(),Sensitive=sensitive.Checked},Count=(long)count.Value,Seconds=(double)seconds.Value,OutputDirectory=folder.Text.Trim(),Format=format.SelectedIndex==0?"txt":format.SelectedIndex==1?"xlsx":"both",Append=append.Checked};}
 void Preview(){bool rep=mode.SelectedIndex==1;suffix.Enabled=!rep;repeat.Enabled=chars.Enabled=rep;append.Enabled=format.SelectedIndex==0;ruleHelp.Text="Omit "+(chain.SelectedIndex==1?"T":"0x")+" from prefix; empty = any."+(rep?"\nExample: "+new string('8',(int)Math.Min(repeat.Value,8))+"; longer repeats also match.":"\nIf both are set, prefix and suffix must both match.");exportHelp.Text=format.SelectedIndex==0?"TXT contains plaintext private keys. Store offline.":"Plaintext private keys. XLSX every 5s / 10k rows; stop completes export.";try{var r=Read().Rule;r.Validate();preview.Tag=TextTone.Accent;preview.ForeColor=palette.Accent;preview.Text="Targets  "+(r.Prefix.Length>0?"prefix "+r.Prefix+"  ·  ":"")+(rep?"last "+r.Repeat+" identical  ·  "+r.Characters:"suffix "+(r.Suffix.Length>0?r.Suffix:"unlimited"))+"\n"+(r.Sensitive?"Match actual output case":"Case-insensitive comparison; checksum format is preserved");}catch(Exception ex){preview.Tag=TextTone.Error;preview.ForeColor=palette.Error;preview.Text=ex.Message;}}
 async Task DetectHardware(){try{var info=await Task.Run(()=>Cuda.Hardware());device.Text=info[0];hardware.Text=info[1];configuration.Text=info[2]+"   ·   256 groups × 64 batch";tips.SetToolTip(configuration,configuration.Text+". CPU affects seeding and verification; GPU and batch affect search throughput.");ready=true;start.Enabled=!busy;status.Text="GPU ready · CPU verified · One result per group · Fresh seeds for every task";}catch(Exception ex){device.Text="No usable NVIDIA CUDA GPU detected";hardware.Text=ex.Message;configuration.Text="Check the NVIDIA driver.";ready=false;Log(ex.Message);}}
 void UI(Action a){if(!IsDisposed&&IsHandleCreated)try{BeginInvoke(a);}catch(InvalidOperationException){}}
 void Log(string text){UI(()=>{if(logs.TextLength>40000)logs.Text=logs.Text.Substring(logs.TextLength-20000);logs.AppendText(text+Environment.NewLine);});}
 void Notice(string text){MessageBox.Show(this,text,"Astra v1.1.0",MessageBoxButtons.OK,MessageBoxIcon.Warning);}
 void ShowLogs(){if(logWindow==null||logWindow.IsDisposed){logWindow=new Form{Text="Astra v1.1.0 · Logs (no private keys)",ClientSize=new Size(760,340),StartPosition=FormStartPosition.CenterParent,Font=Font};logWindow.Controls.Add(logs);logWindow.FormClosing+=(s,e)=>{if(e.CloseReason==CloseReason.UserClosing){e.Cancel=true;logWindow.Hide();}};}PaintControls(logWindow,palette);logWindow.Show(this);WindowTheme.Caption(logWindow,palette);logWindow.BringToFront();}
 void Busy(bool value){busy=value;rulesCard.Enabled=outputCard.Enabled=!value;start.Enabled=!value&&ready;test.Enabled=!value;stop.Enabled=value&&cancel!=null;ApplyPalette(palette);}
 void RequestStop(){if(cancel!=null){cancel.Cancel();stop.Enabled=false;status.Text="Completing verification, flush and Excel export…";}else if(busy)status.Text="Completing self-test, then closing…";}
 async Task Test(){Busy(true);status.Text="Running extended self-test…";try{await Task.Run(()=>SelfTest.Run(true,Log));status.Text="Self-test passed · Addresses, case and GPU / CPU results agree";}catch(Exception ex){status.Text="Self-test failed: "+ex.Message;Log(status.Text);}finally{Busy(false);if(closing)Close();}}
 async Task StartSearch(){Options o;try{o=Read();o.Validate();}catch(Exception ex){Notice(ex.Message);return;}cancel=new CancellationTokenSource();Busy(true);speedValue.Text="— M/s";savedValue.Text="0";elapsedValue.Text="00:00:00";status.Text="Running startup checks and seeding…";try{await Task.Run(()=>Engine.Run(o,cancel.Token,s=>{string speed=(s.Rate/1e6).ToString("F2")+" M/s",saved=s.Saved.ToString("N0")+(s.Target>0?" / "+s.Target:""),elapsed=TimeSpan.FromSeconds(s.Elapsed).ToString(@"hh\:mm\:ss");double factor=s.Probability*s.GroupCandidates<1e-6?s.Probability:(1-Math.Pow(1-s.Probability,s.GroupCandidates))/s.GroupCandidates;double mean=s.Rate>0?1/(s.Rate*factor):double.PositiveInfinity;string summary=s.Stage+" · Mean delivery≈"+Snapshot.Duration(mean)+" · Remaining≈"+(s.Target==0?"unlimited":Snapshot.Duration(mean*Math.Max(0,s.Target-s.Accepted)))+" · GPU "+s.LastKernelMs.ToString("F1")+" ms";UI(()=>{speedValue.Text=speed;savedValue.Text=saved;elapsedValue.Text=elapsed;status.Text=summary;});},Log));}catch(Exception ex){Log("Stopped: "+ex.Message);status.Text="Error: "+ex.Message;Notice(ex.Message);}finally{cancel.Dispose();cancel=null;Busy(false);if(closing)Close();}}
}
